/**
 * User guide: SINGLE SOURCE of the in-app help dialog and of
 * docs/GUIDE_UTILISATEUR.md (generated by `npm run guide`, see
 * scripts/generate-guide.ts). No import here: the file is read directly by
 * Node (type stripping) as well as bundled in the app.
 *
 * Inline formatting: **bold** and `key` (keyboard key or button name).
 */

export type GuideBlock =
  | { type: 'p'; text: string }
  | { type: 'list'; items: string[] }
  | { type: 'table'; headers: string[]; rows: string[][] }

export interface GuideSection {
  id: string
  title: string
  blocks: GuideBlock[]
}

