/** Escapes the characters meaningful in a Markdown table cell. */
function cell(text: string): string {
  return text.replace(/\|/g, '\\|')
}

/**
 * The guide as Markdown (docs/GUIDE_UTILISATEUR.md). Same content and order
 * as the help dialog.
 */
export function guideToMarkdown(sections: readonly GuideSection[] = GUIDE_SECTIONS): string {
  const lines: string[] = [
    `# ${GUIDE_TITLE}`,
    '',
    '<!-- Fichier généré par `npm run guide` depuis src/features/help/guideContent.ts : ne pas modifier à la main. -->',
    '',
    GUIDE_INTRO,
    '',
  ]
  for (const section of sections) {
    lines.push(`## ${section.title}`, '')
    for (const block of section.blocks) {
      if (block.type === 'p') lines.push(block.text, '')
      else if (block.type === 'list') lines.push(...block.items.map((item) => `- ${item}`), '')
      else {
        lines.push(
          `| ${block.headers.map(cell).join(' | ')} |`,
          `| ${block.headers.map(() => '---').join(' | ')} |`,
          ...block.rows.map((row) => `| ${row.map(cell).join(' | ')} |`),
          '',
        )
      }
    }
  }
  return `${lines.join('\n').trimEnd()}\n`
}
